// A tuple to hold user information
using UserInfo = std::tuple<std::string, std::string, std::size_t>;

// Unscoped enum provides named indices for the tuple
enum UserInfoFields { uiName, uiEmail, uiReputation };

void process_user(const UserInfo& uInfo) {
  // Accessing with a magic number is unclear
  auto email_unclear = std::get<1>(uInfo);

  // Accessing with a named enumerator is self-documenting
  auto email_clear = std::get<uiEmail>(uInfo);
}
